@model Umbraco.Bench.Umbraco.Models.Blocks.BlogPostListModel

<section class="mx-auto max-w-6xl px-6 py-16">
    @if (!string.IsNullOrWhiteSpace(Model.Heading))
    {
        <h2 class="text-3xl font-bold tracking-tight text-slate-900">@Model.Heading</h2>
    }
    @if (Model.Posts.Count == 0)
    {
        <p class="mt-6 text-slate-600">No posts yet. Check back soon.</p>
    }
    else
    {
        <div class="mt-10 grid gap-8 md:grid-cols-2">
            @foreach (var post in Model.Posts)
            {
                <article class="group flex flex-col overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200 transition hover:-translate-y-0.5 hover:shadow-xl">
                    <a href="@post.Url" class="flex flex-1 flex-col">
                        @if (post.ImageUrl is not null)
                        {
                            <img src="@post.ImageUrl" alt="@post.ImageAlt" loading="lazy" class="aspect-video w-full object-cover" />
                        }
                        <div class="flex flex-1 flex-col p-6">
                            <time datetime="@post.PublishDate.ToString("yyyy-MM-dd")" class="text-sm text-slate-500">@post.PublishDate.ToString("d MMMM yyyy", System.Globalization.CultureInfo.InvariantCulture)</time>
                            <h3 class="mt-2 text-xl font-semibold text-slate-900 group-hover:text-indigo-600">@post.Title</h3>
                            @if (!string.IsNullOrWhiteSpace(post.Excerpt))
                            {
                                <p class="mt-3 flex-1 text-slate-600">@post.Excerpt</p>
                            }
                            <span class="mt-5 text-sm font-semibold text-indigo-600">Read the post &rarr;</span>
                        </div>
                    </a>
                </article>
            }
        </div>
    }
</section>

