/* Block grid chrome. Views/Partials/blockgrid/ emits Umbraco's standard classes and
   CSS variables; this lays them out so the column spans editors pick are honoured. */
.umb-block-grid__layout-container {
    display: grid;
    grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
}

.umb-block-grid__layout-item {
    grid-column-end: span min(var(--umb-block-grid--item-column-span, 12), var(--umb-block-grid--grid-columns, 12));
    grid-row-end: span var(--umb-block-grid--item-row-span, 1);
}

/* Markup coming out of the rich text editor. */
.rich-text {
    @apply text-lg leading-relaxed text-slate-700;

    & > * + * { @apply mt-5; }
    & h2 { @apply mt-12 text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl; }
    & h3 { @apply mt-8 text-xl font-semibold text-slate-900; }
    & strong { @apply font-semibold text-slate-900; }
    & a { @apply font-medium text-indigo-600 underline underline-offset-2 hover:text-indigo-800; }
    & ul { @apply list-disc space-y-2 pl-6 marker:text-indigo-500; }
    & ol { @apply list-decimal space-y-3 pl-6 marker:font-semibold marker:text-indigo-500; }
    & code { @apply rounded bg-slate-100 px-1.5 py-0.5 font-mono text-[0.9em] text-indigo-700; }
    & blockquote { @apply border-l-4 border-indigo-500 pl-4 italic; }
}

