export const meta = {
  name: 'blog-compliance-review',
  description: 'Audit the MCP-built blog against AGENTS.md / UMBRACO-RULES.md, then adversarially verify findings',
  phases: [{ title: 'Audit' }, { title: 'Verify' }],
}

const ROOT = 'X:/benchmarking/Umbraco.Bench'
const FILES = `
Files written this session (all under ${ROOT}/Umbraco.Bench.Umbraco unless noted):
- Views/blogFrontPage.cshtml, Views/blogPost.cshtml, Views/Shared/_Layout.cshtml
- Views/Partials/blockgrid/Components/{heroBlock,richTextBlock,imageBlock,quoteBlock,blogPostListBlock}.cshtml (adapters)
- Views/Shared/Components/{Hero,RichText,Image,Quote,BlogPostList}/Default.cshtml (component views)
- ViewComponents/{Hero,RichText,Image,Quote,BlogPostList}ViewComponent.cs
- Models/Blocks/{HeroModel,RichTextModel,ImageModel,QuoteModel,BlogPostListModel}.cs, Models/Blog/BlogPostCardModel.cs
- Services/BlogPostService.cs, Composers/BlogComposer.cs
- ${ROOT}/Umbraco.Bench.Frontend/src/site.css (appended block-grid chrome + .rich-text styles)
Schema created over MCP: element types heroBlock, richTextBlock, imageBlock, quoteBlock, blogPostListBlock (Blocks folder);
page types blogFrontPage, blogPost (Pages folder); siteRoot updated to allow blogFrontPage; data types "Blog Front Page Grid", "Blog Post Grid" (Umbraco.BlockGrid);
templates blogFrontPage, blogPost; media folder "Blog" with 5 Unsplash images; content: "The Model Context Blog" under WWW with domain "/", and 2 blogPost children.
The site is running at https://localhost:44317 (use curl -sk with MSYS_NO_PATHCONV=1 in Git Bash). The Umbraco MCP server tools (mcp__umbraco__*) are available via ToolSearch for READ-ONLY inspection.
Read ${ROOT}/AGENTS.md and ${ROOT}/UMBRACO-RULES.md first. Do NOT modify any file or any Umbraco data. Only look inside ${ROOT}.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          rule: { type: 'string', description: 'Which AGENTS.md / UMBRACO-RULES.md rule or correctness concern' },
          evidence: { type: 'string', description: 'Concrete quote / command output proving it' },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          fix: { type: 'string' },
        },
        required: ['title', 'file', 'rule', 'evidence', 'severity', 'fix'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean' },
    reasoning: { type: 'string' },
  },
  required: ['real', 'reasoning'],
}

const DIMENSIONS = [
  { key: 'rendering-pipeline', prompt: `Audit the block RENDERING PIPELINE against AGENTS.md "Rendering blocks — the non-negotiable pipeline": pages use Html.GetBlockGridHtmlAsync; no custom block loops; adapters in Views/Partials/blockgrid/Components/<alias>.cshtml (camelCase alias filenames, capital C folder) receive BlockGridItem<T>, map to a plain model, contain NO markup, invoke a ViewComponent; each block is a ViewComponent rendering Views/Shared/Components/<Name>/Default.cshtml with no explicit view path; component views depend only on the plain model; Views/Shared/Components holds only ViewComponent folders; images via GetCropUrl; friendly extensions only, no injected url/image services. Report only real violations with evidence.` },
  { key: 'code-conventions', prompt: `Audit C#/project CONVENTIONS and correctness: Services/ classes named *Service; no .cs file directly in Models/ root; namespaces follow folders; composers in Composers/ (one per concern) and Program.cs untouched; appsettings untouched; BlogPostService correctness (null handling, ordering newest first, maxItems semantics, DI lifetime); Razor correctness (null-safety, HTML encoding of rich text vs plain text, alt text, date formatting). Also run 'dotnet build' is NOT allowed (site is running and holds a lock) — instead reason from source. Report only real defects or rule violations with evidence.` },
  { key: 'schema-and-content', prompt: `Audit the UMBRACO SCHEMA AND CONTENT against UMBRACO-RULES.md using read-only MCP tools and the uSync folder (Umbraco.Bench.Umbraco/uSync/v18): every new document type is in the correct one of the six folders (Pages/Blocks/…); block element types are isElement and not used as compositions; no content behind compositions; data types not at tree root; aliases English camelCase; media lives in a folder; content root only holds Repositories (WWW) and the site page has domain "/"; uSync export files exist for the new content types, data types, templates, media and content. Also curl https://localhost:44317/ and the two post URLs and confirm HTTP 200, no "Could not render component" fallback, and that every <img src> returns 200. Report only real violations with evidence.` },
]

const results = await pipeline(
  DIMENSIONS,
  d => agent(`${d.prompt}\n\n${FILES}`, { label: `audit:${d.key}`, phase: 'Audit', schema: FINDINGS }),
  (review, d) => parallel((review?.findings ?? []).map(f => () =>
    agent(`You are a skeptical reviewer. Try to REFUTE this claimed issue in the Umbraco.Bench project. Read the actual files / query read-only MCP tools yourself; do not trust the claim's evidence. Mark real=false if the claim is wrong, is not actually required by AGENTS.md/UMBRACO-RULES.md, or is purely stylistic with no rule behind it. Default to real=false if uncertain.\n\nClaim: ${JSON.stringify(f, null, 2)}\n\n${FILES}`,
      { label: `verify:${d.key}:${f.title.slice(0, 40)}`, phase: 'Verify', schema: VERDICT })
      .then(v => ({ ...f, dimension: d.key, verdict: v }))
  ))
)

const all = results.flat().filter(Boolean)
return {
  confirmed: all.filter(f => f.verdict?.real),
  rejected: all.filter(f => !f.verdict?.real).map(f => ({ title: f.title, why: f.verdict?.reasoning })),
}

