@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@using Umbraco.Bench.Umbraco.Services
@inherits UmbracoViewPage<Umbraco.Cms.Core.Models.Blocks.BlockGridItem<BlogPostListBlock>>
@inject BlogPostService BlogPostService
@{
    var model = new BlogPostListModel
    {
        Heading = Model.Content.Heading,
        Posts = Umbraco.AssignedContentItem is { } currentPage
            ? BlogPostService.GetLatestPosts(currentPage, Model.Content.MaxItems)
            : [],
    };
}
@await Component.InvokeAsync("BlogPostList", new { model })
